    "omschakelen_met_timer":  { code: 0x0D, tijd: true,  kanaal_nodig: true }
};

function phcCrc(data) {
    let crc = 0xFFFF;
    for (let b of data) {
        crc ^= b;
        for (let i = 0; i < 8; i++) {
            if (crc & 1) crc = (crc >> 1) ^ 0x8408;
            else crc >>= 1;
        }
    }
    return crc ^ 0xFFFF;
}

const functieKey = msg.functie ? String(msg.functie).toLowerCase().trim() : "";
let functieDef = FUNCTIES[functieKey];
if (!functieDef) return null;

const adres = parseInt(msg.adres, 16);
let payloadBytes = [];

if (functieDef.kanaal_nodig) {
    const kanaal = parseInt(msg.kanaal);
    payloadBytes.push((kanaal << 5) | functieDef.code);
} else {
    payloadBytes.push(functieDef.code);
}

if (functieDef.tijd) {
    const tijdSec = Math.round(parseFloat(msg.tijd));
    payloadBytes.push(tijdSec & 0xFF);
    payloadBytes.push((tijdSec >> 8) & 0xFF);
}

const startheader = [0xFE, 0x00, 0x06, 0x00];
const toggleLen = 0x00 | payloadBytes.length;
const cmdNoCrc = [adres, toggleLen, ...payloadBytes];
const crc = phcCrc([...startheader, ...cmdNoCrc]);
const raw = [...startheader, ...cmdNoCrc, crc & 0xFF, (crc >> 8) & 0xFF];

function escape(data) {
    const out = [];
    for (let b of data) {
        if (b === 0xC0) out.push(0x7D, 0xE0);
        else if (b === 0xC1) out.push(0x7D, 0xE1);
        else if (b === 0x7D) out.push(0x7D, 0x5D);
        else out.push(b);
    }
    return out;
}
const finalFrame = [0xC0, ...escape(raw), 0xC1];
msg.payload = finalFrame.map(b => b.toString(16).padStart(2, "0").toUpperCase()).join(" ");
return msg;

